-- tenant rows: warehouse/client 1 and 2 each get one of everything
do $fx$
declare n integer; w uuid; c uuid; z uuid; s uuid; g uuid; r uuid; cmp uuid; i integer;
begin
  for i in 1..2 loop
    w := ('f1000000-0000-0000-0000-00000000000' || i)::uuid; c := ('f4000000-0000-0000-0000-00000000000' || i)::uuid;
    z := ('f2000000-0000-0000-0000-00000000000' || i)::uuid; s := ('f3000000-0000-0000-0000-00000000000' || i)::uuid;
    begin insert into public.company_master (id, client_id, name) values (('f6000000-0000-0000-0000-00000000000' || i)::uuid, c, 'Co ' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.company_master (id, client_id, name) valu',60); end;
    begin insert into public.contracts (client_id, warehouse_id, start_date, status) values (c, w, current_date, 'ACTIVE'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.contracts (client_id, warehouse_id, start',60); end;
    begin insert into public.space_bookings (client_id, warehouse_id, storage_type, temp_setpoint_c, temp_min, temp_max, brigades_requested, from_date, expected_days) values (c, w, 'FROZEN', -20, -25, -18, 1, current_date, 5); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.space_bookings (client_id, warehouse_id, ',60); end;
    begin insert into public.gate_entries (id, warehouse_id, direction, client_id, lorry_number) values (('f7000000-0000-0000-0000-00000000000' || i)::uuid, w, 'INWARD', c, 'TN01AB000' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.gate_entries (id, warehouse_id, direction',60); end;
    begin insert into public.gate_entry_lines (gate_entry_id, warehouse_id, client_id, line_no, item_name, declared_qty, storage_type) values (('f7000000-0000-0000-0000-00000000000' || i)::uuid, w, c, 1, 'Peas', 10, 'FROZEN'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.gate_entry_lines (gate_entry_id, warehous',60); end;
    begin insert into public.gate_entries (id, warehouse_id, direction, client_id, lorry_number) values (('f7100000-0000-0000-0000-00000000000' || i)::uuid, w, 'OUTWARD', c, 'TN02AB000' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.gate_entries (id, warehouse_id, direction',60); end;
    begin insert into public.inward_receipts (id, receipt_no, warehouse_id, client_id, gate_entry_id) values (('f8000000-0000-0000-0000-00000000000' || i)::uuid, 'GR-MX-' || i, w, c, ('f7000000-0000-0000-0000-00000000000' || i)::uuid); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.inward_receipts (id, receipt_no, warehous',60); end;
    begin insert into public.stock_items (id, client_id, warehouse_id, zone_id, slot_id, slot_code, item_name, unit, quantity) values (('f9000000-0000-0000-0000-00000000000' || i)::uuid, c, w, z, s, 'M' || i || '-S1', 'Peas', 'BOX', 5); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.stock_items (id, client_id, warehouse_id,',60); end;
    begin insert into public.stock_movements (movement_type, stock_item_id, client_id, warehouse_id, to_slot_id, qty_delta) values ('IN', ('f9000000-0000-0000-0000-00000000000' || i)::uuid, c, w, s, 5); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.stock_movements (movement_type, stock_ite',60); end;
    begin insert into public.slot_allocations (client_id, warehouse_id, zone_id, slot_id, brigade_type_id, start_date) values (c, w, z, s, (select id from public.brigade_types where is_default), current_date - 3); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.slot_allocations (client_id, warehouse_id',60); end;
    begin insert into public.labour_entries (warehouse_id, client_id, document_type, document_id, activity, workers, hours) values (w, c, 'INWARD_RECEIPT', ('f8000000-0000-0000-0000-00000000000' || i)::uuid, 'UNLOADING', 2, 1); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.labour_entries (warehouse_id, client_id, ',60); end;
    begin insert into public.dispatch_requests (id, client_id, warehouse_id, to_company_id, requested_date) values (('fa000000-0000-0000-0000-00000000000' || i)::uuid, c, w, ('f6000000-0000-0000-0000-00000000000' || i)::uuid, current_date); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.dispatch_requests (id, client_id, warehou',60); end;
    begin insert into public.dispatch_request_lines (request_id, warehouse_id, client_id, line_no, item_name, quantity) values (('fa000000-0000-0000-0000-00000000000' || i)::uuid, w, c, 1, 'Peas', 1); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.dispatch_request_lines (request_id, wareh',60); end;
    begin insert into public.delivery_challans (challan_no, warehouse_id, client_id, dispatch_request_id, gate_entry_id, to_company_id) values ('DC-MX-' || i, w, c, ('fa000000-0000-0000-0000-00000000000' || i)::uuid, ('f7100000-0000-0000-0000-00000000000' || i)::uuid, ('f6000000-0000-0000-0000-00000000000' || i)::uuid); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.delivery_challans (challan_no, warehouse_',60); end;
    begin insert into public.invoices (id, client_id, warehouse_id, billing_mode, period_from, period_to, status, invoice_date) values (('fb000000-0000-0000-0000-00000000000' || i)::uuid, c, w, 'BOTH', current_date - 30, current_date - 1, 'ISSUED', current_date); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.invoices (id, client_id, warehouse_id, bi',60); end;
    begin insert into public.payments (payment_no, client_id, warehouse_id, amount_paise, method, paid_on) values ('PAY-MX-' || i, c, w, 1000, 'CASH', current_date); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.payments (payment_no, client_id, warehous',60); end;
    begin insert into public.opening_balances (client_id, as_of, amount_paise) values (c, current_date, 1000); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.opening_balances (client_id, as_of, amoun',60); end;
    begin insert into public.client_contacts (client_id, name, email) values (c, 'Contact ' || i, 'c' || i || '@test.local'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.client_contacts (client_id, name, email) ',60); end;
    begin insert into public.client_change_requests (client_id, changes) values (c, '{"city":"X"}'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.client_change_requests (client_id, change',60); end;
    begin insert into public.support_tickets (client_id, warehouse_id, subject) values (c, w, 'Ticket number ' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.support_tickets (client_id, warehouse_id,',60); end;
    begin insert into public.ticket_events (ticket_id, kind, body) select id, 'MESSAGE', 'hello' from public.support_tickets where client_id = c; exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.ticket_events (ticket_id, kind, body) sel',60); end;
    begin insert into public.sensors (id, zone_id, name, type, unit, serial_no, installed_on) values (('fc000000-0000-0000-0000-00000000000' || i)::uuid, z, 'Probe ' || i, 'TEMPERATURE', 'C', 'MX-' || i, current_date); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.sensors (id, zone_id, name, type, unit, s',60); end;
    begin insert into public.alerts (id, kind, severity, warehouse_id, zone_id, sensor_id, opened_at, event_start) values (('fd000000-0000-0000-0000-00000000000' || i)::uuid, 'TEMP_HIGH', 'WARNING', w, z, ('fc000000-0000-0000-0000-00000000000' || i)::uuid, now(), now()); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.alerts (id, kind, severity, warehouse_id,',60); end;
    begin insert into public.alert_stock (alert_id, client_id, client_name, zone_id) values (('fd000000-0000-0000-0000-00000000000' || i)::uuid, c, 'Client ' || i, z); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.alert_stock (alert_id, client_id, warehou',60); end;
    begin insert into public.equipment (id, warehouse_id, zone_id, type, name) values (('fe000000-0000-0000-0000-00000000000' || i)::uuid, w, z, 'COMPRESSOR', 'Comp ' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.equipment (id, warehouse_id, zone_id, typ',60); end;
    begin insert into public.maintenance_tasks (equipment_id, warehouse_id, due_date) values (('fe000000-0000-0000-0000-00000000000' || i)::uuid, w, current_date + 5); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.maintenance_tasks (equipment_id, warehous',60); end;
    begin insert into public.shifts (id, warehouse_id, name, starts_at, ends_at) values (('ff000000-0000-0000-0000-00000000000' || i)::uuid, w, 'Day', '08:00', '16:00'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.shifts (id, warehouse_id, name, starts_at',60); end;
    begin insert into public.vacancies (id, warehouse_id, title) values (('f0100000-0000-0000-0000-00000000000' || i)::uuid, w, 'Loader ' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.vacancies (id, warehouse_id, title) value',60); end;
    begin insert into public.vacancy_salaries values (('f0100000-0000-0000-0000-00000000000' || i)::uuid, 100, 200); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.vacancy_salaries values ((f0100000-0000-',60); end;
    begin insert into public.applicants (id, vacancy_id, full_name) values (('f0200000-0000-0000-0000-00000000000' || i)::uuid, ('f0100000-0000-0000-0000-00000000000' || i)::uuid, 'App ' || i); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.applicants (id, vacancy_id, full_name) va',60); end;
    begin insert into public.interview_rounds (applicant_id, round_no, scheduled_at, interviewer) values (('f0200000-0000-0000-0000-00000000000' || i)::uuid, 1, now(), 'Boss'); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.interview_rounds (applicant_id, round_no,',60); end;
    begin insert into public.alert_rules (warehouse_id, zone_id) values (w, z); exception when others then raise notice 'fixture: % -- %', sqlerrm, left('insert into public.alert_rules (warehouse_id, zone_id, kind)',60); end;
  end loop;
end $fx$;
