insert into public.notification_outbox (channel, to_address, body) values ('EMAIL', 'x@test.local', 'b');
insert into public.client_notices (alert_id, client_id, warehouse_id, status, subject, body) select a.id, s.client_id, a.warehouse_id, 'APPROVED', 's', 'b' from public.alerts a join public.alert_stock s on s.alert_id = a.id;
insert into public.readings (sensor_id, recorded_at, value, raw_value, source) select id, now() - interval '1 hour', -20, -20, 'SENSOR' from public.sensors where serial_no like 'MX-%';
insert into public.readings_hourly (sensor_id, hour, min_value, max_value, avg_value, n) select id, date_trunc('hour', now() - interval '2 hours'), -21, -19, -20, 60 from public.sensors where serial_no like 'MX-%';
